  "programs": {
    "health-safety": {
      "intro": "First Nation Fresh Foods operates a documented work health and safety program covering processing, cool-chain warehousing and delivery. The program is maintained as a controlled set of documents and is available to buyers and auditors on request.",
      "points": [
        {
          "title": "Hazard and risk assessment",
          "body": "Documented assessment of hazards across processing, cutting, cool rooms, loading docks and delivery, with controls assigned and reviewed."
        },
        {
          "title": "Health and safety policy",
          "body": "Management commitment, consultation arrangements and the responsibilities held at every level of the business."
        },
        {
          "title": "Safe work practices",
          "body": "Written safe work procedures for machinery operation, manual handling, chemical handling, cold work and vehicle movements."
        },
        {
          "title": "Training and induction",
          "body": "Induction for all new staff and contractors, with refresher training and competency records maintained for equipment operation."
        },
        {
          "title": "Incident reporting and review",
          "body": "Reporting of incidents and near misses, investigation of causes, and corrective action tracked to completion."
        },
        {
          "title": "Emergency preparedness",
          "body": "Emergency procedures, first aid provision and evacuation arrangements tested and reviewed on a scheduled basis."
        }
      ],
      "docs": [],
      "images": []
    },
    "modern-slavery": {
      "intro": "First Nation Fresh Foods does not tolerate forced labour, servitude, debt bondage or child labour in any part of its operations or supply chain. Our modern slavery program sets out how we assess that risk and what we require of the growers, manufacturers and service providers we buy from.",
      "points": [
        {
          "title": "Our position",
          "body": "Forced labour, servitude, debt bondage, deceptive recruiting and child labour are prohibited throughout our operations and supply chain, without exception."
        },
        {
          "title": "Supplier expectations",
          "body": "Growers, manufacturers and service providers are expected to meet the same standard, and to extend it to their own suppliers."
        },
        {
          "title": "Risk assessment",
          "body": "Supply is assessed for modern slavery risk by commodity, labour model and region, with higher-risk categories reviewed more closely."
        },
        {
          "title": "Due diligence",
          "body": "New suppliers are asked about their labour arrangements, subcontracting and recruitment practices before supply commences."
        },
        {
          "title": "Local sourcing",
          "body": "Sourcing predominantly from local Australian growers and manufacturers materially shortens the supply chain and reduces exposure."
        },
        {
          "title": "Reporting a concern",
          "body": "Any concern about labour conditions in our operations or supply chain can be raised with our administration desk and will be investigated."
        }
      ],
      "docs": [],
      "images": []
    }
  },
